.staffOverlay{position:absolute;inset:0;z-index:150;display:none;background:rgba(0,0,0,.58);backdrop-filter:blur(3px)}.staffOverlay.open{display:block}.staffDrawer{position:absolute;top:0;right:0;bottom:0;width:min(780px,94vw);display:grid;grid-template-rows:auto auto 1fr;background:linear-gradient(160deg,#080b0f,#07090c 62%,#090b0e);border-left:1px solid rgba(252,178,73,.18);box-shadow:-30px 0 70px rgba(0,0,0,.42)}.staffHeader{min-height:82px;padding:0 clamp(18px,1.5vw,26px);display:flex;align-items:center;gap:14px;background:linear-gradient(110deg,rgba(252,178,73,.12),rgba(252,178,73,.05));border-bottom:1px solid rgba(255,255,255,.06)}.staffHeaderIcon{width:46px;height:46px;display:grid;place-items:center;background:linear-gradient(145deg,var(--accentLight),var(--accentDark));color:#151109}.staffHeaderText h2{font-family:var(--fontTitle);font-size:31px;letter-spacing:.04em;font-weight:400}.staffHeaderText p{margin-top:2px;color:#718d99;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.11em}.staffClose{margin-left:auto;width:42px;height:42px;display:grid;place-items:center;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.07)}.staffTabs{min-height:52px;display:flex;align-items:flex-end;gap:5px;padding:0 18px;background:rgba(255,255,255,.025);border-bottom:1px solid rgba(255,255,255,.05)}.staffTab{height:40px;padding:0 15px;background:rgba(255,255,255,.045);color:#a9c0ca;font-family:var(--fontTitle);font-size:17px;letter-spacing:.045em}.staffTab.active{color:#151109;background:var(--accent)}.staffContent{overflow-y:auto;padding:18px}.staffSection{display:none}.staffSection.active{display:block}.staffBlock{padding:16px;margin-bottom:13px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.055)}.staffBlockTitle{font-family:var(--fontTitle);font-size:23px;letter-spacing:.045em}.staffBlockDesc{margin-top:4px;color:#718894;font-size:9px;font-weight:700;line-height:1.5}.formGrid{margin-top:14px;display:grid;grid-template-columns:1fr 1fr;gap:10px}.field{display:flex;flex-direction:column;gap:6px}.field.full{grid-column:1/-1}.field label{color:#7f9ba7;font-size:8px;font-weight:900;text-transform:uppercase;letter-spacing:.11em}.field input,.field select,.field textarea{width:100%;min-height:39px;padding:0 11px;border:1px solid rgba(255,255,255,.08);background:rgba(0,0,0,.2);color:#f4f1e9;font-size:10px}.field textarea{min-height:82px;padding-top:10px;resize:vertical}.field select option{background:#07151b;color:#f4f1e9}.staffActionRow{margin-top:13px;display:flex;justify-content:flex-end;gap:8px}.staffAction{min-height:38px;padding:0 14px;display:flex;align-items:center;gap:7px;background:var(--accent);color:#151109;font-family:var(--fontTitle);font-size:16px;letter-spacing:.045em}.staffAction.secondary{background:rgba(255,255,255,.065);color:#c3d6dd;border:1px solid rgba(255,255,255,.07)}.adminList{margin-top:13px;display:grid;gap:7px}.adminRow{min-height:50px;padding:8px 10px;display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.05)}.adminRowIcon{width:34px;height:34px;display:grid;place-items:center;flex:0 0 auto;background:rgba(252,178,73,.08);border:1px solid rgba(252,178,73,.16);color:#ffd36e}.adminRowInfo{min-width:0}.adminRowName{font-family:var(--fontTitle);font-size:17px;letter-spacing:.04em}.adminRowMeta{margin-top:2px;color:#6f8791;font-size:8px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.adminRowActions{margin-left:auto;display:flex;gap:5px}.miniBtn{width:31px;height:31px;display:grid;place-items:center;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.055);color:#bdd2d9}.miniBtn.danger{color:#ff9da5;background:rgba(229,72,88,.08);border-color:rgba(229,72,88,.12)}
.footer{position:absolute;left:0;right:0;bottom:0;z-index:55;height:var(--footer);padding:0 var(--sidePad);display:flex;align-items:center;gap:14px;background:linear-gradient(90deg,rgba(7,9,12,.95),rgba(16,15,11,.90),rgba(7,9,12,.95));border-top:1px solid rgba(252,178,73,.14)}.footerText{color:#e4dfd3;font-family:var(--fontTitle);font-size:clamp(14px,1.06vw,21px);letter-spacing:.055em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.footerLegend{margin-left:auto;display:flex;align-items:center;gap:8px;color:#7e9ca8;font-size:clamp(7px,.48vw,10px);font-weight:800;text-transform:uppercase;letter-spacing:.09em}.key{min-width:28px;height:26px;padding:0 8px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.33);background:rgba(0,0,0,.16);color:white;font-size:9px;font-weight:900}.toast{position:absolute;right:var(--sidePad);bottom:calc(var(--footer) + 18px);z-index:200;min-width:280px;max-width:min(450px,82vw);padding:13px 15px;display:flex;align-items:center;gap:11px;background:rgba(4,14,18,.97);border:1px solid rgba(252,178,73,.26);border-left:3px solid var(--accent);box-shadow:0 15px 38px rgba(0,0,0,.38);opacity:0;transform:translateY(20px);pointer-events:none;transition:.2s ease}.toast.show{opacity:1;transform:translateY(0)}.toast i{color:var(--accentLight)}.toastText{color:#e4dfd3;font-size:10px;line-height:1.45;font-weight:700}.empty{grid-column:1/-1;min-height:220px;display:grid;place-items:center;text-align:center;color:#78919c;border:1px dashed rgba(252,178,73,.16);background:rgba(255,255,255,.02);padding:30px}.empty i{font-size:42px;color:#fcb249;margin-bottom:14px}.emptyTitle{font-family:var(--fontTitle);font-size:28px;color:#f4f1e9;letter-spacing:.04em}.emptyText{margin-top:7px;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;line-height:1.5}
@media(max-width:1500px){:root{--sidePad:clamp(18px,2.5vw,42px)}}
@media(max-width:1260px){.topbar{grid-template-columns:minmax(180px,.8fr) auto minmax(245px,.75fr);gap:12px}.brandSub{display:none}.mainTab{min-width:84px;padding:0 11px}.mainTab i{display:none}.staffBtn span{display:none}.staffBtn{min-width:45px;width:45px;padding:0}.storeGrid{grid-template-columns:repeat(3,minmax(0,1fr))}.featuredWrap{grid-template-columns:1fr 1.15fr}.featuredSecondary{grid-template-columns:repeat(2,minmax(0,1fr))}.inventoryGrid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:980px){:root{--header:64px;--categoryBar:50px;--footer:40px;--sidePad:16px}.topbar{grid-template-columns:auto 1fr auto}.brandMark{display:none}.brandTitle{font-size:24px}.mainNav{justify-content:center;padding-bottom:8px}.mainTab{min-width:70px;height:38px;font-size:17px;padding:0 8px}.money{min-width:110px;padding:0 9px}.moneyLabel{display:none}.closeBtn{width:42px}.categoryInfo,.panelDesc{display:none}.storeGrid{grid-template-columns:repeat(2,minmax(0,1fr))}.featuredWrap{grid-template-columns:1fr;overflow-y:auto}.featuredGroup{min-height:430px}.featuredSecondary{grid-template-columns:repeat(3,minmax(0,1fr))}.inventoryLayout{grid-template-columns:1fr}.inventorySidebar{display:none}.inventoryGrid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:720px){.brandText{display:none}.topbar{grid-template-columns:1fr auto}.mainNav{justify-content:flex-start;overflow-x:auto}.playerArea{gap:5px}.money{min-width:90px}.moneyValue{font-size:17px}.storeGrid,.inventoryGrid{grid-template-columns:repeat(2,minmax(0,1fr))}.featuredPrimary,.featuredSecondary{grid-template-columns:repeat(2,minmax(0,1fr))}.footerLegend{display:none}.formGrid{grid-template-columns:1fr}.field.full{grid-column:auto}}
@media(max-height:760px){:root{--header:58px;--categoryBar:46px;--footer:36px}.mainTab,.money,.staffBtn,.closeBtn{height:34px}.categoryBtn{height:32px}.panelHeader{min-height:44px}.productCard{min-height:230px}.productInfo{min-height:72px}.productFooter{min-height:30px}.inventoryToolbar{min-height:44px}}
</style>
</head>
<body>
<div class="store" id="store">
<header class="topbar">
  <div class="brand"><div class="brandMark"><i class="fa-solid fa-store"></i></div><div class="brandText"><div class="brandTitle" id="brandTitle">ECHOES OF CLONES SHOP</div><div class="brandSub">Versorgungs- und Ausrüstungsnetz der Republik</div></div></div>
  <nav class="mainNav"><button class="mainTab active" data-page="store"><i class="fa-solid fa-cart-shopping"></i> SHOP</button><button class="mainTab" data-page="inventory"><i class="fa-solid fa-box-open"></i> INVENTAR</button></nav>
  <div class="playerArea"><div class="money"><div class="moneyLabel">Verfügbare Credits</div><div class="moneyValue" id="moneyValue">$0</div></div><button class="staffBtn" id="staffBtn"><i class="fa-solid fa-screwdriver-wrench"></i><span>STAFF</span></button><button class="closeBtn" id="closeBtn"><i class="fa-solid fa-xmark"></i></button></div>
</header>
<div class="categoryBar"><div class="categoryScroller" id="categoryScroller"></div><div class="categoryInfo"><i class="fa-solid fa-circle-info"></i></div></div>
<main class="content">
  <section class="page active" id="page-store"><div class="storePanel"><div class="panelHeader"><div class="panelTitle" id="currentCategoryTitle">ANGEBOTE</div><div class="panelDesc" id="currentCategoryDesc">Bester Preis jeder Kategorie.</div></div><div class="storeGrid" id="storeGrid"></div></div></section>
  <section class="page" id="page-inventory"><div class="inventoryLayout"><aside class="inventorySidebar"><div class="inventoryAvatar"><i class="fa-solid fa-user-astronaut"></i></div><div class="inventoryName">MEIN INVENTAR</div><div class="inventorySub">Käufe werden per SteamID64 gespeichert</div><div class="inventoryStats"><div class="invStat"><div class="invStatLabel">Gegenstände</div><div class="invStatValue" id="inventoryCount">0</div></div><div class="invStat"><div class="invStatLabel">Dauerhaft</div><div class="invStatValue" id="permanentCount">0</div></div><div class="invStat"><div class="invStatLabel">Kategorien</div><div class="invStatValue" id="ownedCategoryCount">0</div></div></div><div class="inventoryHelp">Dauerhafte Käufe bleiben gespeichert. Waffen, Modelle und Upgrades kannst du hier abrufen. Entities, Fahrzeuge und Begleiter spawnen im Rahmen der Serverlimits.</div></aside><section class="inventoryMain"><div class="inventoryToolbar"><div class="inventoryTitle">BESITZ</div><div class="inventorySearch"><i class="fa-solid fa-magnifying-glass"></i><input id="inventorySearchInput" type="text" placeholder="Suchen..."></div></div><div class="inventoryGrid" id="inventoryGrid"></div></section></div></section>
</main>
<footer class="footer"><div class="footerText">ECHOES OF CLONES • ANGEBOTE + MODELLE + UPGRADES</div><div class="footerLegend"><span class="key">ESC</span> schließen <span class="key">LMB</span> auswählen</div></footer>

<div class="staffOverlay" id="staffOverlay"><div class="staffDrawer">
  <div class="staffHeader"><div class="staffHeaderIcon"><i class="fa-solid fa-screwdriver-wrench"></i></div><div class="staffHeaderText"><h2>SHOP-VERWALTUNG</h2><p>Dauerhafte Speicherung auf dem Server</p></div><button class="staffClose" id="staffClose"><i class="fa-solid fa-xmark"></i></button></div>
  <div class="staffTabs"><button class="staffTab active" data-staff="products">PRODUKTE</button><button class="staffTab" data-staff="categories">KATEGORIEN</button><button class="staffTab" data-staff="list">LISTE</button></div>
  <div class="staffContent">
    <section class="staffSection active" id="staff-products"><div class="staffBlock"><div class="staffBlockTitle" id="productFormTitle">NEUES PRODUKT ERSTELLEN</div><div class="staffBlockDesc">Produktbilder sind nicht nötig. Die 3D-Vorschau kommt aus previewModel, dem SWEP-WorldModel oder dem Entity-Model.</div><div class="formGrid">
      <div class="field"><label>Name</label><input id="itemName" type="text" placeholder="DC-17M Commando"></div>
      <div class="field"><label>Kategorie</label><select id="itemCategory"></select></div>
      <div class="field"><label>Typ</label><select id="itemType"><option value="model">Modell</option><option value="upgrade">Upgrade</option><option value="other">Sonstiges</option></select></div>
      <div class="field"><label>Preis</label><input id="itemPrice" type="number" min="0" placeholder="125000"></div>
      <div class="field full"><label>Klasse / Interne ID</label><input id="itemClass" type="text" placeholder="weapon_x / models/... / entity_x"></div>
      <div class="field full"><label>3D-Vorschaumodell</label><input id="itemPreviewModel" type="text" placeholder="models/.../model.mdl (optional, wird sonst automatisch erkannt)"></div>
      <div class="field"><label>Seltenheit</label><select id="itemRarity"><option value="cyan">Cyan</option><option value="blue">Blau</option><option value="green">Grün</option><option value="gold">Gold</option><option value="red">Rot</option></select></div>
      <div class="field"><label>Kaufart</label><select id="itemPurchaseType"><option value="permanent">Dauerhaft</option><option value="temporary">Temporär</option><option value="consumable">Verbrauchbar</option></select></div>
      <div class="field"><label>Dauer (Sekunden)</label><input id="itemDuration" type="number" min="0" placeholder="0"></div>
      <div class="field full"><label>Beschreibung</label><textarea id="itemDescription" placeholder="Produktbeschreibung..."></textarea></div>
    </div><div class="staffActionRow"><button class="staffAction secondary" id="resetItemForm"><i class="fa-solid fa-rotate-left"></i> ABBRECHEN</button><button class="staffAction" id="saveItemBtn"><i class="fa-solid fa-floppy-disk"></i> PRODUKT SPEICHERN</button></div></div></section>
    <section class="staffSection" id="staff-categories"><div class="staffBlock"><div class="staffBlockTitle" id="categoryFormTitle">NEUE KATEGORIE</div><div class="staffBlockDesc">Neue Kategorien erscheinen automatisch in der Leiste und steuern ihr günstigstes Produkt zu den Angeboten bei.</div><div class="formGrid"><div class="field"><label>Name</label><input id="categoryName" type="text" placeholder="Verbrauchbares"></div><div class="field"><label>ID</label><input id="categoryId" type="text" placeholder="verbrauchbares"></div><div class="field"><label>Font-Awesome-Icon</label><input id="categoryIcon" type="text" placeholder="fa-solid fa-box"></div><div class="field"><label>Beschreibung</label><input id="categoryDesc" type="text" placeholder="Verbrauchsgegenstände"></div></div><div class="staffActionRow"><button class="staffAction secondary" id="resetCategoryForm"><i class="fa-solid fa-rotate-left"></i> ABBRECHEN</button><button class="staffAction" id="saveCategoryBtn"><i class="fa-solid fa-floppy-disk"></i> KATEGORIE SPEICHERN</button></div><div class="adminList" id="categoryAdminList"></div></div></section>
    <section class="staffSection" id="staff-list"><div class="staffBlock"><div class="staffBlockTitle">KONFIGURIERTE PRODUKTE</div><div class="staffBlockDesc">Produkte bearbeiten oder löschen. Dauerhafte Käufe bleiben erhalten, auch wenn das Produkt aus dem Shop entfernt wird.</div><div class="adminList" id="itemAdminList"></div></div></section>
  </div>
</div></div>
<div class="toast" id="toast"><i class="fa-solid fa-circle-check"></i><div class="toastText" id="toastText">Erledigt.</div></div>
</div>
<script>
(()=>{"use strict";
const state={storeName:"Echoes of Clones Store",money:0,isStaff:false,activePage:"store",activeCategory:"__featured__",categories:[],products:[],inventory:[]};
const $=id=>document.getElementById(id);const els={brandTitle:$("brandTitle"),moneyValue:$("moneyValue"),staffBtn:$("staffBtn"),closeBtn:$("closeBtn"),categoryScroller:$("categoryScroller"),title:$("currentCategoryTitle"),desc:$("currentCategoryDesc"),storeGrid:$("storeGrid"),inventoryGrid:$("inventoryGrid"),inventorySearch:$("inventorySearchInput"),inventoryCount:$("inventoryCount"),permanentCount:$("permanentCount"),ownedCategoryCount:$("ownedCategoryCount"),staffOverlay:$("staffOverlay"),staffClose:$("staffClose"),toast:$("toast"),toastText:$("toastText"),itemName:$("itemName"),itemCategory:$("itemCategory"),itemType:$("itemType"),itemPrice:$("itemPrice"),itemClass:$("itemClass"),itemPreviewModel:$("itemPreviewModel"),itemRarity:$("itemRarity"),itemPurchaseType:$("itemPurchaseType"),itemDuration:$("itemDuration"),itemDescription:$("itemDescription"),saveItemBtn:$("saveItemBtn"),resetItemForm:$("resetItemForm"),productFormTitle:$("productFormTitle"),categoryName:$("categoryName"),categoryId:$("categoryId"),categoryIcon:$("categoryIcon"),categoryDesc:$("categoryDesc"),saveCategoryBtn:$("saveCategoryBtn"),resetCategoryForm:$("resetCategoryForm"),categoryFormTitle:$("categoryFormTitle"),categoryAdminList:$("categoryAdminList"),itemAdminList:$("itemAdminList")};
let toastTimer=null,editingProduct="",editingCategory="";
const moneyFmt=n=>"$"+Number(n||0).toLocaleString("en-US");
const esc=v=>String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
const attr=esc;
function bridge(name,...args){try{if(window.grnStore&&typeof window.grnStore[name]==="function"){window.grnStore[name](...args);return true}}catch(e){}return false}
function clippedPreviewRect(el){let r=el.getBoundingClientRect(),left=r.left,top=r.top,right=r.right,bottom=r.bottom,p=el.parentElement;while(p&&p!==document.body&&p!==document.documentElement){const cs=getComputedStyle(p);const clipX=/(auto|scroll|hidden)/.test(cs.overflowX)||/(auto|scroll|hidden)/.test(cs.overflow);const clipY=/(auto|scroll|hidden)/.test(cs.overflowY)||/(auto|scroll|hidden)/.test(cs.overflow);if(clipX||clipY){const pr=p.getBoundingClientRect();if(clipX){left=Math.max(left,pr.left);right=Math.min(right,pr.right)}if(clipY){top=Math.max(top,pr.top);bottom=Math.min(bottom,pr.bottom)}}p=p.parentElement}left=Math.max(0,left);top=Math.max(0,top);right=Math.min(window.innerWidth,right);bottom=Math.min(window.innerHeight,bottom);const w=right-left,h=bottom-top;return w>=24&&h>=24?{x:left,y:top,w,h}:null}
let previewSyncRAF=0;function syncModelPreviewsNow(){previewSyncRAF=0;const slots=[];document.querySelectorAll(".modelSlot[data-preview-id]").forEach(el=>{const style=getComputedStyle(el);if(style.display==="none"||style.visibility==="hidden")return;const r=clippedPreviewRect(el);if(!r)return;slots.push({key:el.dataset.previewKey||el.dataset.previewId,id:el.dataset.previewId,x:r.x,y:r.y,w:r.w,h:r.h})});bridge("syncPreviews",JSON.stringify({viewportW:window.innerWidth,viewportH:window.innerHeight,slots}))}
function schedulePreviewSync(){if(previewSyncRAF)return;previewSyncRAF=requestAnimationFrame(syncModelPreviewsNow)}
function toast(text,ok=true){els.toastText.textContent=text;els.toast.querySelector("i").className=ok?"fa-solid fa-circle-check":"fa-solid fa-circle-exclamation";els.toast.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>els.toast.classList.remove("show"),1800)}
function iconForType(t){return({weapon:"fa-solid fa-gun",model:"fa-solid fa-user-astronaut",vehicle:"fa-solid fa-shuttle-space",entity:"fa-solid fa-cube",pet:"fa-solid fa-paw",upgrade:"fa-solid fa-arrow-up-right-dots",rank:"fa-solid fa-medal",other:"fa-solid fa-box"})[t]||"fa-solid fa-box"}
function labelForType(t){return({weapon:"WAFFE",model:"MODELL",vehicle:"FAHRZEUG",entity:"ENTITY",pet:"BEGLEITER",upgrade:"UPGRADE",rank:"RANG",other:"SONSTIGES"})[t]||"GEGENSTAND"}
function setPage(page){state.activePage=page;document.querySelectorAll(".mainTab").forEach(b=>b.classList.toggle("active",b.dataset.page===page));document.querySelectorAll(".page").forEach(p=>p.classList.toggle("active",p.id==="page-"+page));if(page==="inventory")renderInventory();bridge("hidePreview")}
function renderCategories(){els.categoryScroller.innerHTML="";const f=document.createElement("button");f.className="categoryBtn"+(state.activeCategory==="__featured__"?" active":"");f.innerHTML='<i class="fa-solid fa-star"></i><span>ANGEBOTE</span>';f.onclick=()=>{state.activeCategory="__featured__";renderCategories();renderStore()};els.categoryScroller.appendChild(f);state.categories.forEach(c=>{const b=document.createElement("button");b.className="categoryBtn"+(state.activeCategory===c.id?" active":"");b.innerHTML='<i class="'+attr(c.icon||"fa-solid fa-folder")+'"></i><span>'+esc(c.name)+'</span>';b.onclick=()=>{state.activeCategory=c.id;renderCategories();renderStore()};els.categoryScroller.appendChild(b)});els.itemCategory.innerHTML=state.categories.map(c=>'<option value="'+attr(c.id)+'">'+esc(c.name)+'</option>').join("")}
function ownedProduct(id){return state.inventory.some(i=>i.productID===id&&i.purchaseType==="permanent")}
function card(product,deal){const a=document.createElement("article");a.className="productCard";a.dataset.rarity=product.rarity||"cyan";const badge=product.purchaseType==="temporary"?"TEMPORÄR":product.purchaseType==="consumable"?"VERBRAUCHBAR":"DAUERHAFT";const owned=ownedProduct(product.id);const previewKey="store:"+String(product.id);a.innerHTML='<div class="productBadge"><i class="'+(badge==="DAUERHAFT"?"fa-solid fa-infinity":"fa-regular fa-clock")+'"></i>'+badge+'</div>'+(deal?'<div class="dealBadge"><i class="fa-solid fa-tag"></i>'+esc(deal)+'</div>':'')+'<div class="productVisual"><div class="modelSlot" data-preview-key="'+attr(previewKey)+'" data-preview-id="'+attr(product.id)+'"></div></div><div class="productInfo"><div class="productName">'+esc(product.name)+'</div><div class="productType">'+esc(labelForType(product.type))+'</div></div><div class="productFooter"><div class="productPrice">'+moneyFmt(product.price)+'</div><button class="buyButton'+(owned?' owned':'')+'">'+(owned?'<i class="fa-solid fa-check"></i> GEKAUFT':'<i class="fa-solid fa-cart-shopping"></i> KAUFEN')+'</button></div>';
const buy=a.querySelector(".buyButton");if(!owned)buy.onclick=e=>{e.stopPropagation();if(!bridge("buy",product.id))toast("Verbindung zu GMod nicht verfügbar.",false)};return a}
function renderStore(){if(state.activeCategory==="__featured__")return renderFeatured();const cat=state.categories.find(c=>c.id===state.activeCategory);els.title.textContent=cat?cat.name:"SHOP";els.desc.textContent=cat?cat.desc:"";els.storeGrid.className="storeGrid";els.storeGrid.innerHTML="";const items=state.products.filter(p=>p.category===state.activeCategory);if(!items.length){els.storeGrid.innerHTML='<div class="empty"><div><i class="fa-solid fa-box-open"></i><div class="emptyTitle">KEINE PRODUKTE</div><div class="emptyText">Staff kann dieser Kategorie Produkte hinzufügen.</div></div></div>';return}items.forEach(p=>els.storeGrid.appendChild(card(p,"")))}
function featuredDeals(){return state.categories.map(c=>{const items=state.products.filter(p=>p.category===c.id).slice().sort((a,b)=>Number(a.price||0)-Number(b.price||0));return items.length?{category:c,item:items[0]}:null}).filter(Boolean).sort((a,b)=>Number(a.item.price||0)-Number(b.item.price||0))}
function renderFeatured(){els.title.textContent="ANGEBOTE";els.desc.textContent="Das günstigste Produkt jeder Kategorie wird automatisch ausgewählt.";els.storeGrid.className="storeGrid";const d=featuredDeals();if(!d.length){els.storeGrid.innerHTML='<div class="empty"><div><i class="fa-solid fa-star"></i><div class="emptyTitle">KEINE ANGEBOTE</div><div class="emptyText">Füge Produkte über das Staff-Panel hinzu.</div></div></div>';return}els.storeGrid.innerHTML='<div class="featuredWrap" style="grid-column:1/-1"><section class="featuredGroup"><div class="featuredHead"><i class="fa-solid fa-fire"></i><div class="featuredTitle">BESTE ANGEBOTE</div><div class="featuredMeta">TOP '+Math.min(2,d.length)+'</div></div><div class="featuredBody featuredPrimary" id="featuredPrimary"></div></section><section class="featuredGroup"><div class="featuredHead"><i class="fa-solid fa-tags"></i><div class="featuredTitle">ANGEBOTE NACH KATEGORIE</div><div class="featuredMeta">'+d.length+' categories</div></div><div class="featuredBody featuredSecondary" id="featuredSecondary"></div></section></div>';const p=$("featuredPrimary"),s=$("featuredSecondary");d.slice(0,2).forEach(x=>p.appendChild(card(x.item,"BESTER PREIS • "+x.category.name)));const rest=d.slice(2);if(rest.length)rest.forEach(x=>s.appendChild(card(x.item,"BESTER PREIS • "+x.category.name)));else s.innerHTML='<div class="empty"><div><i class="fa-solid fa-layer-group"></i><div class="emptyTitle">WEITERE KATEGORIEN</div><div class="emptyText">Neue Kategorien mit Produkten erscheinen hier.</div></div></div>'}
function invActionLabel(i){if(i.type==="model")return i.equipped?"AUSGERÜSTET":"AUSRÜSTEN";if(i.type==="weapon")return"ABRUFEN";if(["entity","vehicle","pet"].includes(i.type))return"SPAWNEN";if(i.type==="upgrade")return"ANWENDEN";return"BENUTZEN"}
function renderInventory(){const q=(els.inventorySearch.value||"").trim().toLowerCase();const arr=state.inventory.filter(i=>!q||String(i.name).toLowerCase().includes(q)||labelForType(i.type).toLowerCase().includes(q));els.inventoryGrid.innerHTML="";if(!arr.length)els.inventoryGrid.innerHTML='<div class="empty"><div><i class="fa-solid fa-box-open"></i><div class="emptyTitle">INVENTAR LEER</div></div></div>';else arr.forEach((i,index)=>{const c=document.createElement("div");c.className="inventoryCard";let exp=i.expires>0?" • läuft ab "+new Date(i.expires*1000).toLocaleString():"";const slotKey="inventory:"+String(i.id||i.productID||index)+":"+index;c.innerHTML='<div class="inventoryCardIcon"><div class="modelSlot inventoryModelSlot" data-preview-key="'+attr(slotKey)+'" data-preview-id="'+attr(i.productID)+'"></div></div><div class="inventoryCardInfo"><div class="inventoryCardName">'+esc(i.name)+'</div><div class="inventoryCardMeta">'+esc(labelForType(i.type))+' • '+(i.purchaseType==="permanent"?"Dauerhaft":i.purchaseType==="temporary"?"Temporär":"Verbrauchbar")+esc(exp)+'</div><button class="inventoryAction'+(i.equipped?' equipped':'')+'">'+esc(invActionLabel(i))+'</button></div>';const b=c.querySelector(".inventoryAction");if(i.equipped&&i.type==="model")b.disabled=true;else b.onclick=()=>bridge("useItem",i.productID);els.inventoryGrid.appendChild(c)});els.inventoryCount.textContent=state.inventory.length;els.permanentCount.textContent=state.inventory.filter(i=>i.purchaseType==="permanent").length;els.ownedCategoryCount.textContent=new Set(state.inventory.map(i=>i.category)).size}
function renderStaff(){els.staffBtn.classList.toggle("visible",!!state.isStaff);els.categoryAdminList.innerHTML="";state.categories.forEach(c=>{const r=document.createElement("div");r.className="adminRow";r.innerHTML='<div class="adminRowIcon"><i class="'+attr(c.icon||"fa-solid fa-folder")+'"></i></div><div class="adminRowInfo"><div class="adminRowName">'+esc(c.name)+'</div><div class="adminRowMeta">ID: '+esc(c.id)+(c.protected?' • GESCHÜTZT':'')+'</div></div><div class="adminRowActions"><button class="miniBtn edit"><i class="fa-solid fa-pen"></i></button><button class="miniBtn danger" '+(c.protected?'disabled style="opacity:.35"':'')+'><i class="fa-solid fa-trash"></i></button></div>';r.querySelector(".edit").onclick=()=>editCategory(c);const del=r.querySelector(".danger");if(!c.protected)del.onclick=()=>bridge("deleteCategory",c.id);els.categoryAdminList.appendChild(r)});els.itemAdminList.innerHTML="";state.products.forEach(p=>{const cat=state.categories.find(c=>c.id===p.category);const r=document.createElement("div");r.className="adminRow";r.innerHTML='<div class="adminRowIcon"><i class="'+attr(iconForType(p.type))+'"></i></div><div class="adminRowInfo"><div class="adminRowName">'+esc(p.name)+'</div><div class="adminRowMeta">'+esc(cat?cat.name:p.category)+' • '+moneyFmt(p.price)+' • '+esc(p.className||"keine Klasse")+'</div></div><div class="adminRowActions"><button class="miniBtn edit"><i class="fa-solid fa-pen"></i></button><button class="miniBtn danger"><i class="fa-solid fa-trash"></i></button></div>';r.querySelector(".edit").onclick=()=>editProduct(p);r.querySelector(".danger").onclick=()=>bridge("deleteProduct",p.id);els.itemAdminList.appendChild(r)})}
function resetProduct(){editingProduct="";els.productFormTitle.textContent="NEUES PRODUKT ERSTELLEN";[els.itemName,els.itemPrice,els.itemClass,els.itemPreviewModel,els.itemDuration,els.itemDescription].forEach(x=>x.value="");els.itemRarity.value="cyan";els.itemPurchaseType.value="permanent";els.itemType.value="weapon"}
function editProduct(p){editingProduct=p.id;els.productFormTitle.textContent="BEARBEITE • "+p.name;els.itemName.value=p.name||"";els.itemCategory.value=p.category||"";els.itemType.value=p.type||"other";els.itemPrice.value=p.price||0;els.itemClass.value=p.className||"";els.itemPreviewModel.value=p.previewModel||"";els.itemRarity.value=p.rarity||"cyan";els.itemPurchaseType.value=p.purchaseType||"permanent";els.itemDuration.value=p.duration||0;els.itemDescription.value=p.description||"";setStaffTab("products")}
function saveProduct(){const payload={editID:editingProduct,name:els.itemName.value,category:els.itemCategory.value,type:els.itemType.value,price:Number(els.itemPrice.value||0),className:els.itemClass.value,previewModel:els.itemPreviewModel.value,spawnModel:els.itemPreviewModel.value,rarity:els.itemRarity.value,purchaseType:els.itemPurchaseType.value,duration:Number(els.itemDuration.value||0),description:els.itemDescription.value};if(!payload.name.trim())return toast("Ein Name ist erforderlich.",false);if(!bridge("saveProduct",JSON.stringify(payload)))toast("Verbindung zu GMod nicht verfügbar.",false)}
function resetCategory(){editingCategory="";els.categoryFormTitle.textContent="NEUE KATEGORIE";[els.categoryName,els.categoryId,els.categoryIcon,els.categoryDesc].forEach(x=>x.value="");els.categoryId.disabled=false}
function editCategory(c){editingCategory=c.id;els.categoryFormTitle.textContent="BEARBEITE • "+c.name;els.categoryName.value=c.name||"";els.categoryId.value=c.id||"";els.categoryId.disabled=true;els.categoryIcon.value=c.icon||"";els.categoryDesc.value=c.desc||"";setStaffTab("categories")}
function saveCategory(){const payload={editID:editingCategory,name:els.categoryName.value,id:els.categoryId.value,icon:els.categoryIcon.value,desc:els.categoryDesc.value};if(!payload.name.trim())return toast("Ein Name ist erforderlich.",false);if(!bridge("saveCategory",JSON.stringify(payload)))toast("Verbindung zu GMod nicht verfügbar.",false)}
function setStaffTab(name){document.querySelectorAll(".staffTab").forEach(b=>b.classList.toggle("active",b.dataset.staff===name));document.querySelectorAll(".staffSection").forEach(s=>s.classList.toggle("active",s.id==="staff-"+name))}
function setData(data){if(!data||typeof data!=="object")return;bridge("clearPreviews");state.storeName=data.storeName||state.storeName;state.money=Number(data.money||0);state.isStaff=!!data.isStaff;state.categories=Array.isArray(data.categories)?data.categories:[];state.products=Array.isArray(data.products)?data.products:[];state.inventory=Array.isArray(data.inventory)?data.inventory:[];if(state.activeCategory!=="__featured__"&&!state.categories.some(c=>c.id===state.activeCategory))state.activeCategory="__featured__";els.brandTitle.textContent=String(state.storeName).toUpperCase();els.moneyValue.textContent=moneyFmt(state.money);renderCategories();renderStore();renderInventory();renderStaff();if(editingProduct&&!state.products.some(p=>p.id===editingProduct))resetProduct();if(editingCategory&&!state.categories.some(c=>c.id===editingCategory))resetCategory()}
document.querySelectorAll(".mainTab").forEach(b=>b.onclick=()=>setPage(b.dataset.page));document.querySelectorAll(".staffTab").forEach(b=>b.onclick=()=>setStaffTab(b.dataset.staff));els.inventorySearch.oninput=renderInventory;els.staffBtn.onclick=()=>{if(state.isStaff){els.staffOverlay.classList.add("open");schedulePreviewSync()}};els.staffClose.onclick=()=>{els.staffOverlay.classList.remove("open");schedulePreviewSync()};els.staffOverlay.onclick=e=>{if(e.target===els.staffOverlay){els.staffOverlay.classList.remove("open");schedulePreviewSync()}};els.saveItemBtn.onclick=saveProduct;els.resetItemForm.onclick=resetProduct;els.saveCategoryBtn.onclick=saveCategory;els.resetCategoryForm.onclick=resetCategory;els.closeBtn.onclick=()=>bridge("close");window.addEventListener("keydown",e=>{if(e.key==="Escape"){if(els.staffOverlay.classList.contains("open")){els.staffOverlay.classList.remove("open");schedulePreviewSync()}else bridge("close")}});
document.addEventListener("scroll",schedulePreviewSync,true);window.addEventListener("resize",schedulePreviewSync);new MutationObserver(schedulePreviewSync).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["class","style"]});
window.CloneFallStore={setData,notify:toast,syncPreviews:schedulePreviewSync,staffSaved(kind){if(kind==="product")resetProduct();if(kind==="category")resetCategory();},openCategory(id){state.activeCategory=id==="featured"?"__featured__":id;setPage("store");renderCategories();renderStore();schedulePreviewSync()}};
renderCategories();renderStore();renderInventory();schedulePreviewSync();
})();
</script>
